async update(id: string, data: Partial<Employee>): Promise<Employee | null> {
  const allowedFields: (keyof Employee)[] = [
    'firstName',
    'lastName',
    'email',
    'managerId',
    'department',
    'hireDate',
  ];
  const sanitized: Partial<Employee> = {};
  for (const key of allowedFields) {
    if (key in data) {
      (sanitized as Record<string, unknown>)[key] = (data as Record<string, unknown>)[key];
    }
  }
  return this.repo.update(id, sanitized);
}

extras.new_content:
async update(id: string, data: Partial<Employee>): Promise<Employee | null> {
  const existing = await this.repo.findById(id);
  if (!existing) {
    return null;
  }

  const allowedFields: (keyof Employee)[] = [
    'firstName',
    'lastName',
    'email',
    'managerId',
    'department',
    'hireDate',
  ];
  const sanitized: Partial<Employee> = {};
  for (const key of allowedFields) {
    if (key in data) {
      (sanitized as Record<string, unknown>)[key] = (data as Record<string, unknown>)[key];
    }
  }
  const updated = await this.repo.update(id, sanitized);
  if (!updated) {
    return null;
  }

  const now = new Date();
  const auditRecord: AuditRecord = {
    id: crypto.randomUUID(),
    entityType: 'Employee',
    entityId: updated.id,
    action: 'UPDATE',
    oldValues: this.employeeToRecord(existing),
    newValues: this.employeeToRecord(updated),
    performedBy: 'system',
    performedAt: now,
    ipAddress: undefined,
    userAgent: undefined,
    createdAt: now,
  };
  await this.auditRepo.create(auditRecord);

  return updated;
}

